package main

import "testing"

func TestAdd(t *testing.T) {
	cases := []struct {
		name string
		a, b int
		want int
	}{
		{name: "small positive", a: 2, b: 3, want: 5},
		{name: "zeros", a: 0, b: 0, want: 0},
		{name: "negative and positive", a: -1, b: 1, want: 0},
		{name: "both negative", a: -5, b: -7, want: -12},
		{name: "large positive", a: 1 << 60, b: 1 << 60, want: 1 << 61},
		{name: "large mixed", a: 4_000_000_000_000_000_000, b: -1_000_000_000_000_000_000, want: 3_000_000_000_000_000_000},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := add(tc.a, tc.b)
			if got != tc.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.want)
			}
		})
	}
}

